    if let Some(urls) = matches.get_many::<Url>("uri_opt") {
        for url in urls {
            hosts.insert(url.clone());
        }
    }
    for path in get_many_paths(matches, "uri_file") {
        for line in wordlist::read_lines(&path) {
            match Url::parse(&line) {
                Ok(url) if url.scheme() == "http" || url.scheme() == "https" => {
                    hosts.insert(url);
                }
                _ => println!("Invalid URL: {}", line),
            }
        }
    }
    if hosts.is_empty() {
        println!("No valid hosts were provided - exiting");
        process::exit(2);
    }
    hosts
}

fn get_prefixes(matches: &ArgMatches) -> BTreeSet<String> {
    let mut prefixes = BTreeSet::new();
    prefixes.insert(String::new());
    for path in get_many_paths(matches, "prefix_file") {
        for line in wordlist::read_lines(&path) {
            prefixes.insert(line);
        }
    }
    for prefix in get_many_strings(matches, "prefixes") {
        prefixes.insert(prefix);
    }
    prefixes
}

fn get_extensions(matches: &ArgMatches) -> BTreeSet<String> {
    let mut extensions = BTreeSet::new();
    if !matches.get_flag("force_extension") {
        extensions.insert(String::new());
    }
    for path in get_many_paths(matches, "extension_file") {
        for line in wordlist::read_lines(&path) {
            extensions.insert(line);
        }
    }
    for extension in get_many_strings(matches, "extensions") {
        extensions.insert(extension);
    }
    extensions
}

fn get_length_blacklist(matches: &ArgMatches) -> Vec<Range<usize>> {
    let mut ranges = Vec::new();
    for value in get_many_strings(matches, "length_blacklist") {
        let parts: Vec<&str> = value.split('-').collect();
        if parts.len() > 2 {
            panic!("Ranges must be in the form `150-300`");
        } else if parts.len() == 2 {
            let start: usize = parts[0]
                .parse()
                .expect("Length must be integers");
            let end: usize = parts[1]
                .parse()
                .expect("Ranges must be in the form `150-300`");
            if start >= end {
                panic!("The start of a range must be smaller than the end");
            }
            ranges.push(start..end.wrapping_add(1));
        } else {
            let number: usize = parts[0]
                .parse()
                .expect("Length range must be integers");
            ranges.push(number..number.wrapping_add(1));
        }
    }
    ranges.sort_by(|a, b| a.start.cmp(&b.start).then(a.end.cmp(&b.end)));
    ranges
}

pub fn get_global_opts(matches: &ArgMatches) -> Option<GlobalOpts> {
    let hosts = get_hosts(matches);
    let prefixes = get_prefixes(matches);
    let extensions = get_extensions(matches);
    let length_blacklist = get_length_blacklist(matches);

    let mut wordlist_paths = get_many_paths(matches, "wordlist");
    if wordlist_paths.is_empty() {
        if let Some(path) = crate::find_default_wordlist() {
            wordlist_paths.push(path);
        } else {
            return None;
        }
    }
    let mut wordlist = BTreeSet::new();
    for path in &wordlist_paths {
        for line in wordlist::read_lines(path) {
            wordlist.insert(wordlist::clean_word(&line));
        }
    }

    let verb = match matches
        .get_one::<String>("http_verb")
        .map(|value| value.to_lowercase())
        .as_deref()
    {
        Some("head") => HttpVerb::Head,
        Some("post") => HttpVerb::Post,
        _ => HttpVerb::Get,
    };

    let mut output_file = matches.get_one::<PathBuf>("output_file").cloned();
    let mut json_file = matches.get_one::<PathBuf>("json_file").cloned();
    let mut xml_file = matches.get_one::<PathBuf>("xml_file").cloned();
    if let Some(all) = matches.get_one::<PathBuf>("output_all") {
        if output_file.is_none() {
            output_file = Some(PathBuf::from(format!("{}.txt", all.display())));
        }
        if json_file.is_none() {
            json_file = Some(PathBuf::from(format!("{}.json", all.display())));
        }
        if xml_file.is_none() {
            xml_file = Some(PathBuf::from(format!("{}.xml", all.display())));
        }
    }

    let proxy = if matches.get_flag("burp") {
        Some("http://localhost:8080".to_owned())
    } else if matches.get_flag("no_proxy") {
        Some(String::new())
    } else {
        matches.get_one::<String>("proxy").cloned()
    };

    Some(GlobalOpts {
        hosts,
        wordlist_paths,
        wordlist,
        prefixes,
        extensions,
        verb,
        force_extension: matches.get_flag("force_extension"),
        ext_sub: matches.get_flag("ext_sub"),
        ignore_cert: matches.get_flag("ignore_cert"),
        show_htaccess: matches.get_flag("show_htaccess"),
        timeout: *matches.get_one::<u32>("timeout").unwrap(),
        max_errors: *matches.get_one::<u32>("max_errors").unwrap(),
        json_file,
        no_color: matches.get_flag("no_color"),
        output_file,
        xml_file,
        length_blacklist,
        proxy,
        max_threads: *matches.get_one::<u32>("max_threads").unwrap(),
        wordlist_split: *matches.get_one::<u32>("wordlist_split").unwrap(),
        throttle: matches.get_one::<u32>("milliseconds").copied(),
        username: matches.get_one::<String>("username").cloned(),
        password: matches.get_one::<String>("password").cloned(),
        scan_listable: matches.get_flag("scan_listable"),
        max_recursion_depth: matches.get_one::<i32>("max_recursion_depth").copied(),
        disable_recursion: matches.get_flag("disable_recursion"),
        scrape_listable: matches.get_flag("scrape_listable"),
        user_agent: matches.get_one::<String>("user_agent").cloned(),
        cookies: get_many_strings(matches, "cookie"),
        headers: get_many_strings(matches, "header"),
        silent: matches.get_flag("silent"),
        verbose: matches.get_count("verbose"),
        code_blacklist: matches
