use std::fs;
use std::path::Path;

const WINDOWS_1252_HIGH: [char; 32] = [
    '\u{20ac}', '\u{0081}', '\u{201a}', '\u{0192}', '\u{201e}', '\u{2026}', '\u{2020}', '\u{2021}',
    '\u{02c6}', '\u{2030}', '\u{0160}', '\u{2039}', '\u{0152}', '\u{008d}', '\u{017d}', '\u{008f}',
    '\u{0090}', '\u{2018}', '\u{2019}', '\u{201c}', '\u{201d}', '\u{2022}', '\u{2013}', '\u{2014}',
    '\u{02dc}', '\u{2122}', '\u{0161}', '\u{203a}', '\u{0153}', '\u{009d}', '\u{017e}', '\u{0178}',
];

fn decode_windows_1252(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|&byte| match byte {
            0x80..=0x9f => WINDOWS_1252_HIGH[(byte - 0x80) as usize],
            _ => byte as char,
        })
        .collect()
}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> String {
    let units: Vec<u16> = bytes
        .chunks_exact(2)
        .map(|chunk| {
            if little_endian {
                u16::from_le_bytes([chunk[0], chunk[1]])
            } else {
                u16::from_be_bytes([chunk[0], chunk[1]])
            }
        })
        .collect();
    char::decode_utf16(units)
        .map(|result| result.unwrap_or(char::REPLACEMENT_CHARACTER))
        .collect()
}

fn looks_like_utf16(bytes: &[u8], little_endian: bool) -> bool {
    if bytes.len() < 4 || bytes.len() % 2 != 0 {
        return false;
    }
    let zero_index = if little_endian { 1 } else { 0 };
    let pairs = bytes.len() / 2;
    let zeroes = bytes
        .chunks_exact(2)
        .filter(|chunk| chunk[zero_index] == 0)
        .count();
    // Ordinary UTF-16 text in the Basic Multilingual Plane has a zero byte
    // in a large proportion of its code units.
    zeroes * 3 >= pairs
}

fn decode_file(bytes: &[u8]) -> String {
    if bytes.starts_with(&[0xff, 0xfe]) {
        decode_utf16(bytes, true)
    } else if bytes.starts_with(&[0xfe, 0xff]) {
        decode_utf16(bytes, false)
    } else if let Ok(text) = std::str::from_utf8(bytes) {
        // A file of ASCII UTF-16 without a byte-order mark is also valid
        // UTF-8 as a byte sequence, because it contains NUL bytes. Prefer
        // the UTF-16 interpretation when the NUL pattern is pronounced.
        if looks_like_utf16(bytes, true) && bytes.iter().filter(|&&b| b == 0).count() > 2 {
            decode_utf16(bytes, true)
        } else if looks_like_utf16(bytes, false) && bytes.iter().filter(|&&b| b == 0).count() > 2 {
            decode_utf16(bytes, false)
        } else {
            text.to_owned()
        }
    } else if looks_like_utf16(bytes, true) {
        decode_utf16(bytes, true)
    } else if looks_like_utf16(bytes, false) {
        decode_utf16(bytes, false)
    } else {
        decode_windows_1252(bytes)
    }
}

pub fn clean_word(word: &str) -> String {
    let mut cleaned = word;
    if let Some(stripped) = cleaned.strip_prefix('/') {
        cleaned = stripped;
    }
    if let Some(stripped) = cleaned.strip_suffix('/') {
        cleaned = stripped;
    }
    cleaned.to_owned()
}

pub fn read_lines(path: &Path) -> Vec<String> {
    let bytes = fs::read(path).unwrap();
    if bytes.is_empty() {
        panic!(
            "Error detecting file encoding of {} - is the file empty?",
            path.display()
        );
    }
    let text = decode_file(&bytes);
    text.lines().map(|line| line.to_owned()).collect()
}
