use serde::Serialize;
use std::env;
use std::fs::File;
use std::io::{self, IsTerminal, Write};
use std::path::PathBuf;
use std::sync::OnceLock;
use url::Url;

#[derive(Clone, Debug, Serialize)]
pub struct ContentItem {
    pub url: Url,
    pub code: u32,
    pub size: usize,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
    #[serde(skip)]
    pub contents: String,
}

impl ContentItem {
    pub fn new(url: Url, is_directory: bool) -> Self {
        Self {
            url,
            code: 0,
            size: 0,
            is_directory,
            is_listable: false,
            redirect_url: String::new(),
            found_from_listable: false,
            contents: String::new(),
        }
    }

    pub fn parent_url(&self) -> Url {
        let mut parent = self.url.clone();
        parent.set_query(None);
        parent.set_fragment(None);
        parent.path_segments_mut().unwrap().pop();
        parent
    }
}

pub fn colored_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        if let Ok(value) = env::var("CLICOLOR_FORCE") {
            if value != "0" {
                return true;
            }
        }
        if env::var_os("NO_COLOR").is_some() {
            return false;
        }
        if let Ok(value) = env::var("CLICOLOR") {
            return value != "0" && io::stdout().is_terminal();
        }
        io::stdout().is_terminal()
    })
}

fn colored_code(code: u32, use_color: bool) -> String {
    if !use_color || !colored_enabled() {
        return code.to_string();
    }
    let color = match code {
        200..=299 => 32,
        300..=399 => 36,
        400..=499 => 31,
        500..=599 => 33,
        _ => return code.to_string(),
    };
    format!("\x1b[{}m{}\x1b[0m", color, code)
}

pub fn item_to_string(item: &ContentItem, use_color: bool, show_htaccess: bool) -> Option<String> {
    if !show_htaccess && item.code == 403 && item.url.path().contains("/.ht") {
        return None;
    }

    let prefix = if item.is_listable {
        if colored_enabled() {
            "\x1b[1mL \x1b[0m".to_owned()
        } else {
            "L ".to_owned()
        }
    } else if item.is_directory {
        "D ".to_owned()
    } else {
        "+ ".to_owned()
    };

    if item.found_from_listable {
        return Some(format!("{}{} (SCRAPED)", prefix, item.url));
    }

    let code = colored_code(item.code, use_color);
    if item.redirect_url.is_empty() {
        Some(format!(
            "{}{} (CODE:{}|SIZE:{})",
            prefix, item.url, code, item.size
        ))
    } else {
        Some(format!(
            "{}{} (CODE:{}|SIZE:{}|DEST:{})",
            prefix, item.url, code, item.size, item.redirect_url
        ))
    }
}

pub fn sort_items(items: &mut [ContentItem]) {
    items.sort_by(|a, b| {
        a.parent_url()
            .cmp(&b.parent_url())
            .then_with(|| a.url.cmp(&b.url))
    });
}

#[derive(Default)]
pub struct OutputFiles {
    pub txt: Option<File>,
    pub json: Option<File>,
    pub xml: Option<File>,
}

fn create_file(path: &PathBuf) -> File {
    File::create(path).unwrap_or_else(|error| {
        panic!("couldn't create {}: {}", path.display(), error);
    })
}

pub fn create_output_files(
    txt: &Option<PathBuf>,
    json: &Option<PathBuf>,
    xml: &Option<PathBuf>,
) -> OutputFiles {
    OutputFiles {
        txt: txt.as_ref().map(create_file),
        json: json.as_ref().map(create_file),
        xml: xml.as_ref().map(create_file),
    }
}

pub fn write_to_file(file: &mut File, content: &str) {
    file.write_all(content.as_bytes()).unwrap();
}
EOF
