use crate::arg_parse::{GlobalOpts, HttpVerb};
use crate::output::ContentItem;
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_long, c_void};
use std::ptr;
use std::sync::Once;
use url::Url;

const CURLOPT_WRITEDATA: i32 = 10001;
const CURLOPT_URL: i32 = 10002;
const CURLOPT_PROXY: i32 = 10004;
const CURLOPT_READDATA: i32 = 10009;
const CURLOPT_ERRORBUFFER: i32 = 10010;
const CURLOPT_WRITEFUNCTION: i32 = 20011;
const CURLOPT_READFUNCTION: i32 = 20012;
const CURLOPT_TIMEOUT: i32 = 13;
const CURLOPT_USERAGENT: i32 = 10018;
const CURLOPT_COOKIE: i32 = 10022;
const CURLOPT_HTTPHEADER: i32 = 10023;
const CURLOPT_HEADERDATA: i32 = 10029;
const CURLOPT_NOBODY: i32 = 44;
const CURLOPT_POST: i32 = 47;
const CURLOPT_FOLLOWLOCATION: i32 = 52;
const CURLOPT_SSL_VERIFYPEER: i32 = 64;
const CURLOPT_HEADERFUNCTION: i32 = 20079;
const CURLOPT_HTTPGET: i32 = 80;
const CURLOPT_SSL_VERIFYHOST: i32 = 81;
const CURLOPT_NOSIGNAL: i32 = 99;

const CURLINFO_RESPONSE_CODE: i32 = 2097154;
const CURLINFO_REDIRECT_URL: i32 = 1048576 + 31;

#[repr(C)]
struct CurlSlist {
    data: *mut c_char,
    next: *mut CurlSlist,
}

#[link(name = "curl")]
extern "C" {
    fn curl_global_init(flags: c_long) -> i32;
    fn curl_easy_init() -> *mut c_void;
    fn curl_easy_cleanup(handle: *mut c_void);
    fn curl_easy_reset(handle: *mut c_void);
    fn curl_easy_setopt(handle: *mut c_void, option: i32, ...) -> i32;
    fn curl_easy_perform(handle: *mut c_void) -> i32;
    fn curl_easy_getinfo(handle: *mut c_void, info: i32, ...) -> i32;
    fn curl_easy_strerror(code: i32) -> *const c_char;
    fn curl_slist_append(list: *mut CurlSlist, string: *const c_char) -> *mut CurlSlist;
    fn curl_slist_free_all(list: *mut CurlSlist);
