fn curl_error(code: i32, extra: &str) -> String {
    let description = unsafe {
        let pointer = curl_easy_strerror(code);
        if pointer.is_null() {
            "Unknown error".to_owned()
        } else {
            CStr::from_ptr(pointer).to_string_lossy().into_owned()
        }
    };
    if extra.is_empty() {
        format!("[{}] {}", code, description)
    } else {
        format!("[{}] {} ({})", code, description, extra)
    }
}

extern "C" fn write_callback(
    pointer: *mut c_void,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if userdata.is_null() || pointer.is_null() {
        return 0;
    }
    unsafe {
        let body = &mut *(userdata as *mut Vec<u8>);
        let slice = std::slice::from_raw_parts(pointer as *const u8, total);
        body.extend_from_slice(slice);
    }
