pub struct CurlClient {
    handle: *mut c_void,
    error_buffer: Vec<u8>,
}

// A client is only ever used by the thread that owns it.
unsafe impl Send for CurlClient {}

impl CurlClient {
    pub fn new() -> Self {
        static INIT: Once = Once::new();
        INIT.call_once(|| unsafe {
            curl_global_init(3);
        });
        let handle = unsafe { curl_easy_init() };
        assert!(!handle.is_null(), "failed to initialise curl");
        Self {
            handle,
            error_buffer: vec![0; 256],
        }
    }

    fn set_long(&mut self, option: i32, value: c_long) -> Result<(), String> {
        let code = unsafe { curl_easy_setopt(self.handle, option, value) };
        if code == 0 {
            Ok(())
        } else {
            Err(curl_error(code, ""))
        }
    }

    fn set_pointer(&mut self, option: i32, value: *mut c_void) -> Result<(), String> {
        let code = unsafe { curl_easy_setopt(self.handle, option, value) };
        if code == 0 {
            Ok(())
        } else {
            Err(curl_error(code, ""))
        }
    }

    fn perform_request(
        &mut self,
        url: &Url,
        is_directory: bool,
        opts: &GlobalOpts,
    ) -> Result<ContentItem, String> {
        unsafe { curl_easy_reset(self.handle) }
        self.error_buffer.iter_mut().for_each(|byte| *byte = 0);

        let mut request_url = url.clone();
        if let (Some(username), Some(password)) = (&opts.username, &opts.password) {
            let _ = request_url.set_username(username);
            let _ = request_url.set_password(Some(password));
        }

        let url_string = CString::new(request_url.as_str()).unwrap();
        let code = unsafe { curl_easy_setopt(self.handle, CURLOPT_URL, url_string.as_ptr()) };
        if code != 0 {
            return Err(curl_error(code, ""));
        }

        self.set_pointer(
            CURLOPT_ERRORBUFFER,
            self.error_buffer.as_mut_ptr() as *mut c_void,
        )?;
        self.set_long(CURLOPT_NOSIGNAL, 1)?;
        self.set_long(CURLOPT_FOLLOWLOCATION, 0)?;
        self.set_long(CURLOPT_TIMEOUT, opts.timeout as c_long)?;

        match opts.verb {
            HttpVerb::Get => self.set_long(CURLOPT_HTTPGET, 1)?,
            HttpVerb::Head => self.set_long(CURLOPT_NOBODY, 1)?,
            HttpVerb::Post => {
                self.set_long(CURLOPT_POST, 1)?;
                self.set_pointer(
                    CURLOPT_READFUNCTION,
                    read_callback as extern "C" fn(*mut c_void, usize, usize, *mut c_void) -> usize
                        as *mut c_void,
                )?;
                self.set_pointer(CURLOPT_READDATA, ptr::null_mut())?;
            }
        }

        if opts.ignore_cert {
            self.set_long(CURLOPT_SSL_VERIFYPEER, 0)?;
            self.set_long(CURLOPT_SSL_VERIFYHOST, 0)?;
        }

        let proxy_string;
        if let Some(proxy) = &opts.proxy {
            proxy_string = CString::new(proxy.as_str()).unwrap();
            let code = unsafe { curl_easy_setopt(self.handle, CURLOPT_PROXY, proxy_string.as_ptr()) };
            if code != 0 {
                return Err(curl_error(code, ""));
            }
        }

        let user_agent_string;
        if let Some(user_agent) = &opts.user_agent {
            user_agent_string = CString::new(user_agent.as_str()).unwrap();
            let code = unsafe {
                curl_easy_setopt(self.handle, CURLOPT_USERAGENT, user_agent_string.as_ptr())
            };
            if code != 0 {
                return Err(curl_error(code, ""));
            }
        }

        let cookie_string;
        if !opts.cookies.is_empty() {
            cookie_string = CString::new(opts.cookies.join("; ")).unwrap();
            let code = unsafe { curl_easy_setopt(self.handle, CURLOPT_COOKIE, cookie_string.as_ptr()) };
            if code != 0 {
                return Err(curl_error(code, ""));
            }
        }

        let mut body: Vec<u8> = Vec::new();
        self.set_pointer(
            CURLOPT_WRITEFUNCTION,
            write_callback as extern "C" fn(*mut c_void, usize, usize, *mut c_void) -> usize
                as *mut c_void,
        )?;
        self.set_pointer(
            CURLOPT_WRITEDATA,
            &mut body as *mut Vec<u8> as *mut c_void,
        )?;
        self.set_pointer(
            CURLOPT_HEADERFUNCTION,
            discard_callback as extern "C" fn(*mut c_void, usize, usize, *mut c_void) -> usize
                as *mut c_void,
        )?;
        self.set_pointer(CURLOPT_HEADERDATA, ptr::null_mut())?;

        let header_strings: Vec<CString> = opts
            .headers
            .iter()
            .map(|header| CString::new(header.as_str()).unwrap())
            .collect();
        let mut header_list: *mut CurlSlist = ptr::null_mut();
        for header in &header_strings {
            header_list = unsafe { curl_slist_append(header_list, header.as_ptr()) };
        }
        if !header_list.is_null() {
            let result = self.set_pointer(CURLOPT_HTTPHEADER, header_list as *mut c_void);
            if let Err(error) = result {
                unsafe { curl_slist_free_all(header_list) };
                return Err(error);
            }
        }

        let perform_code = unsafe { curl_easy_perform(self.handle) };
        if !header_list.is_null() {
            unsafe { curl_slist_free_all(header_list) };
        }
        if perform_code != 0 {
            let extra = {
                let end = self
                    .error_buffer
                    .iter()
                    .position(|&byte| byte == 0)
                    .unwrap_or(self.error_buffer.len());
                String::from_utf8_lossy(&self.error_buffer[..end]).into_owned()
            };
            return Err(curl_error(perform_code, &extra));
        }

        let mut response_code: c_long = 0;
        unsafe {
            curl_easy_getinfo(
                self.handle,
                CURLINFO_RESPONSE_CODE,
                &mut response_code as *mut c_long,
            )
        };
        let code = response_code as u32;

        let redirect_url = if code == 301 || code == 302 {
            let mut redirect_pointer: *const c_char = ptr::null();
            let info_code = unsafe {
                curl_easy_getinfo(
                    self.handle,
                    CURLINFO_REDIRECT_URL,
                    &mut redirect_pointer as *mut *const c_char,
                )
            };
            let redirect = if info_code == 0 && !redirect_pointer.is_null() {
                unsafe { CStr::from_ptr(redirect_pointer).to_str().ok() }
            } else {
                None
            };
            redirect.unwrap().to_owned()
        } else {
            String::new()
        };

        let size = body.len();
        let contents = String::from_utf8_lossy(&body).into_owned().to_lowercase();
        let is_listable = is_directory
            && (contents.contains("directory listing for")
                || contents.contains("parent directory")
                || contents.contains("up to higher"));

        Ok(ContentItem {
            url: url.clone(),
            code,
            size,
            is_directory,
            is_listable,
            redirect_url,
            found_from_listable: false,
            contents,
        })
    }
}

impl Drop for CurlClient {
    fn drop(&mut self) {
        if !self.handle.is_null() {
            unsafe { curl_easy_cleanup(self.handle) };
        }
    }
}

pub fn request(
    client: &mut CurlClient,
    url: &Url,
    is_directory: bool,
    opts: &GlobalOpts,
) -> ContentItem {
    log::trace!("Requesting {}", url);
    let item = match client.perform_request(url, is_directory, opts) {
        Ok(item) => item,
        Err(error) => {
            println!("Curl error after requesting {} : {}", url, error);
            return ContentItem::new(url.clone(), is_directory);
        }
    };

    if !is_directory
        && (item.code == 301 || item.code == 302)
        && item.redirect_url == format!("{}/", url)
    {
        let directory_url = Url::parse(&item.redirect_url).unwrap();
        return request(client, &directory_url, true, opts);
    }
    item
}
