use std::collections::BTreeMap;

pub fn generate_report(
    hosts: &BTreeMap<Url, Vec<ContentItem>>,
    terminal: bool,
    use_color: bool,
    show_htaccess: bool,
) -> String {
    let mut report = String::new();
    for (host, items) in hosts {
        if terminal {
            report.push_str(&format!("\nDirble Scan Report for {}:\n", host));
        } else {
            report.push_str(&format!("Dirble Scan Report for {}:\n", host));
        }
        for item in items {
            if let Some(text) = item_to_string(item, use_color, show_htaccess) {
                if item.is_directory {
                    report.push('\n');
                }
                if terminal {
                    report.push_str("  ");
                }
                report.push_str(&text);
                report.push('\n');
            }
        }
        if !terminal {
            report.push('\n');
        }
    }
    report
}

pub fn generate_xml(items: &[ContentItem]) -> String {
    let mut xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<dirble_scan>\n".to_owned();
    for item in items {
        xml.push_str(&format!(
            "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>\n",
            item.url,
            item.code,
            item.size,
            item.is_directory,
            item.is_listable,
            item.redirect_url,
            item.found_from_listable
        ));
    }
    xml.push_str("</dirble_scan>");
    xml
}
