cat > src/output_thread.rs <<'EOF'
use crate::output::{generate_report, generate_xml, item_to_string, sort_items, write_to_file, ContentItem, OutputFiles};
use std::collections::BTreeMap;
use std::io::Write;
use std::sync::mpsc::Receiver;
use url::Url;

pub enum OutputMessage {
    Info(String),
    Warning(String),
    Item(Url, ContentItem),
    Files(OutputFiles),
    Finish,
}

pub struct OutputConfig {
    pub silent: bool,
    pub show_htaccess: bool,
    pub interactive: bool,
    pub no_color: bool,
}

pub fn output_thread(
    receiver: Receiver<OutputMessage>,
    hosts: Vec<Url>,
    config: OutputConfig,
) {
    let mut items_by_host: BTreeMap<Url, Vec<ContentItem>> = hosts
        .into_iter()
        .map(|host| (host, Vec::new()))
        .collect();
    let mut files = OutputFiles::default();
    let use_color = config.interactive && !config.no_color;

    while let Ok(message) = receiver.recv() {
        match message {
            OutputMessage::Info(text) => {
                if !config.silent {
                    println!("{}", text);
                }
            }
            OutputMessage::Warning(text) => {
                println!("{}", text);
            }
            OutputMessage::Item(host, item) => {
                if !config.silent {
                    if let Some(text) = item_to_string(&item, use_color, config.show_htaccess) {
                        println!("{}", text);
                    }
                }
                items_by_host.entry(host).or_default().push(item);
            }
            OutputMessage::Files(new_files) => {
                files = new_files;
            }
            OutputMessage::Finish => break,
        }
    }

    log::debug!("Received signal to end, generating the report");

    for items in items_by_host.values_mut() {
        sort_items(items);
    }

    if config.interactive {
        print!(
            "{}",
            generate_report(&items_by_host, true, use_color, config.show_htaccess)
        );
        let _ = std::io::stdout().flush();
    }

    if let Some(file) = &mut files.txt {
        let report = generate_report(&items_by_host, false, false, config.show_htaccess);
        write_to_file(file, &report);
    }

    let all_items: Vec<&ContentItem> = items_by_host
        .values()
        .flat_map(|items| items.iter())
        .collect();

    if let Some(file) = &mut files.json {
        let _ = file.write_all(b"[");
        for item in &all_items[..all_items.len() - 1] {
            let _ = file.write_all(serde_json::to_string(item).unwrap().as_bytes());
            let _ = file.write_all(b",\n");
        }
        let _ = file.write_all(serde_json::to_string(all_items[all_items.len() - 1]).unwrap().as_bytes());
        let _ = file.write_all(b"]");
    }

    if let Some(file) = &mut files.xml {
        let owned: Vec<ContentItem> = all_items.iter().map(|item| (*item).clone()).collect();
        let xml = generate_xml(&owned);
        write_to_file(file, &xml);
    }
}
