            }
            let name_start = cursor;
            while cursor < bytes.len()
                && !bytes[cursor].is_ascii_whitespace()
                && bytes[cursor] != b'='
                && bytes[cursor] != b'>'
                && bytes[cursor] != b'/'
            {
                cursor += 1;
            }
            let name = &html[name_start..cursor];
            while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                cursor += 1;
