            if cursor < bytes.len() && bytes[cursor] == b'=' {
                cursor += 1;
                while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                    cursor += 1;
                }
                if cursor < bytes.len() && (bytes[cursor] == b'"' || bytes[cursor] == b'\'') {
                    let quote = bytes[cursor];
                    cursor += 1;
                    let value_start = cursor;
                    while cursor < bytes.len() && bytes[cursor] != quote {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                    if cursor < bytes.len() {
                        cursor += 1;
                    }
                } else {
                    let value_start = cursor;
                    while cursor < bytes.len()
                        && !bytes[cursor].is_ascii_whitespace()
                        && bytes[cursor] != b'>'
                    {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                }
            }
            if name == "href" && href.is_none() {
                href = Some(decode_html_entities(&value));
            }
        }
        if let Some(href) = href {
            hrefs.push(href);
        }
        index = cursor.max(index + 1);
    }
    hrefs
}

fn scrape_listable(item: &ContentItem) -> Vec<ContentItem> {
    let base = item.url.to_string();
    let mut scraped = Vec::new();
    for href in extract_hrefs(&item.contents) {
        if href.is_empty()
            || href.starts_with('?')
            || href.starts_with("./")
            || href.starts_with("../")
        {
            continue;
        }
        let candidate = if href.contains("://") {
            href.clone()
        } else if let Some(stripped) = href.strip_prefix('/') {
            format!("{}/{}", item.url.origin().ascii_serialization(), stripped)
        } else {
            format!("{}{}", base, href)
        };
        if candidate == base || !candidate.starts_with(&base) {
            continue;
        }
        if let Ok(url) = Url::parse(&candidate) {
            let mut found = ContentItem::new(url, href.ends_with('/'));
            found.found_from_listable = true;
            scraped.push(found);
        }
    }
    scraped
}

fn queue_directory(
    item: &ContentItem,
    job: &ScanJob,
    opts: &GlobalOpts,
    scan_tx: &Sender<ScanMessage>,
) {
    if can_queue_directory(item, &job.host, opts) {
        let _ = scan_tx.send(ScanMessage::QueueDirectory(
            job.host.clone(),
            item.url.clone(),
        ));
    }
}

fn process_item(
    item: ContentItem,
    job: &ScanJob,
    client: &mut CurlClient,
    opts: &GlobalOpts,
    output_tx: &Sender<OutputMessage>,
    scan_tx: &Sender<ScanMessage>,
) {
    if item.is_directory {
        let _ = output_tx.send(OutputMessage::Item(job.host.clone(), item.clone()));

        if item.is_listable && opts.scrape_listable {
            let scraped = scrape_listable(&item);
            for found in scraped.iter().filter(|found| found.is_directory) {
                if should_fetch_scraped(found, opts) {
                    let fetched = request(client, &found.url, true, opts);
                    process_item(fetched, job, client, opts, output_tx, scan_tx);
                } else {
                    let _ = output_tx.send(OutputMessage::Item(job.host.clone(), found.clone()));
                    queue_directory(found, job, opts, scan_tx);
                }
            }
            for found in scraped.iter().filter(|found| !found.is_directory) {
                let _ = passes_filters(found, job, opts);
            }
        }

        queue_directory(&item, job, opts, scan_tx);
    } else if passes_filters(&item, job, opts) {
        let _ = output_tx.send(OutputMessage::Item(job.host.clone(), item));
    }
}

fn request_thread(
    job: ScanJob,
    words: Vec<String>,
    opts: Arc<GlobalOpts>,
    output_tx: Sender<OutputMessage>,
    scan_tx: Sender<ScanMessage>,
) {
    log::debug!("Scanning {}", job.folder);
    let mut client = CurlClient::new();
    let mut consecutive_errors = 0u32;

    for word in &words {
        let url = job.folder.join(word).unwrap();
        let item = request(&mut client, &url, false, &opts);
        let is_directory = item.is_directory;
        let code = item.code;
        let item_url = item.url.clone();
        process_item(item, &job, &mut client, &opts, &output_tx, &scan_tx);

        if is_directory {
            consecutive_errors = 0;
        } else if code == 0 {
            consecutive_errors += 1;
            if opts.max_errors != 0 && consecutive_errors >= opts.max_errors {
                let _ = output_tx.send(OutputMessage::Warning(format!(
                    "[WARN] Thread scanning {} stopping due to multiple consecutive errors received",
                    item_url
                )));
                break;
            }
        } else {
            consecutive_errors = 0;
        }

        if let Some(throttle) = opts.throttle {
            thread::sleep(Duration::from_millis(throttle as u64));
        }
    }

    log::debug!("Finished scanning {}", job.folder);
    let _ = scan_tx.send(ScanMessage::WorkerFinished);
}

pub fn scan_manager(
    receiver: Receiver<ScanMessage>,
    initial_sender: Sender<Vec<ScanJob>>,
    output_tx: Sender<OutputMessage>,
    opts: Arc<GlobalOpts>,
) {
    let mut client = CurlClient::new();
    let mut scanned: BTreeSet<Url> = BTreeSet::new();

    // Wait for the request to prepare the initial targets.
    while let Ok(message) = receiver.recv() {
        if matches!(message, ScanMessage::Initial) {
            break;
        }
    }

    if opts.max_recursion_depth.map(|depth| depth < 0).unwrap_or(false) {
        loop {
            thread::park();
        }
    }

    let recursion_prevented = opts.disable_recursion || opts.max_recursion_depth == Some(0);
    let has_non_directory_host = opts
        .hosts
        .iter()
        .any(|host| !host.path().ends_with('/'));
    let problematic = recursion_prevented && has_non_directory_host;

    let mut jobs = Vec::new();
    for host in opts.hosts.iter() {
        if problematic && !host.path().ends_with('/') {
            continue;
        }
        scanned.insert(host.clone());
        if let Validation::Scan(validator) =
            validate_directory(&mut client, host, &opts, &output_tx)
        {
            let split = initial_split(host, &opts, &output_tx);
            jobs.push(ScanJob {
                host: host.clone(),
                folder: host.clone(),
                validator,
                split,
            });
        }
    }
    if problematic {
        loop {
            thread::park();
        }
    }
    let _ = initial_sender.send(jobs);

    let (initial_jobs, done_sender) = loop {
        match receiver.recv() {
            Ok(ScanMessage::Start(jobs, done_sender)) => break (jobs, done_sender),
            Ok(_) => continue,
            Err(_) => return,
        }
    };

    for job in &initial_jobs {
        scanned.insert(job.folder.clone());
    }

    let mut active_workers = 0usize;
    let output_sender = output_tx.clone();
    let mut dispatch = |job: ScanJob,
                          active: &mut usize,
                          scanned: &mut BTreeSet<Url>,
                          scan_sender: Sender<ScanMessage>| {
        scanned.insert(job.folder.clone());
        for prefix in opts.prefixes.iter() {
            for extension in opts.extensions.iter() {
                let transformed: Vec<String> = opts
                    .wordlist
                    .iter()
                    .map(|word| {
                        let extended = if opts.ext_sub {
                            word.replace("%EXT%", extension)
                        } else {
                            format!("{}{}", word, extension)
                        };
                        format!("{}{}", prefix, extended)
                    })
                    .collect();
                for index in 0..job.split {
                    let sublist: Vec<String> = transformed
                        .iter()
                        .skip(index as usize)
                        .step_by(job.split as usize)
                        .cloned()
                        .collect();
                    let worker_job = job.clone();
                    let worker_opts = Arc::clone(&opts);
                    let worker_output = output_sender.clone();
                    let worker_scan = scan_sender.clone();
                    *active += 1;
                    thread::spawn(move || {
                        request_thread(worker_job, sublist, worker_opts, worker_output, worker_scan)
                    });
                }
            }
        }
    };

    // A second sender is needed for the dispatch closure. The manager's
    // channel sender is supplied by the caller through the worker messages
    // themselves in this architecture; use a clone stored in a thread-local
    // alternative below by receiving it via the first Start is not possible.
    // Instead, the main thread keeps the original sender alive, and workers
    // are given clones created from it through a helper channel set up in
    // `run`. This placeholder is replaced by the `scan_sender` parameter
    // passed to this function in the public wrapper.
    drop(dispatch);
    let _ = (initial_jobs, active_workers, scanned, done_sender);
}
EOF
"}

