use crate::arg_parse::GlobalOpts;
use crate::output::ContentItem;
use crate::output_thread::OutputMessage;
use crate::request::{request, CurlClient};
use rand::distributions::Alphanumeric;
use rand::Rng;
use std::collections::BTreeSet;
use std::sync::mpsc::{Receiver, Sender};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use url::Url;

#[derive(Clone, Debug)]
enum ValidatorSize {
    Exact(usize),
    Diff(usize),
}

#[derive(Clone, Debug)]
pub struct Validator {
    code: u32,
    redirect_url: Option<String>,
    size: Option<ValidatorSize>,
}

impl Validator {
    fn matches(&self, item: &ContentItem) -> bool {
        if item.code != self.code {
            return false;
        }
        if let Some(redirect_url) = &self.redirect_url {
            return &item.redirect_url == redirect_url;
        }
        match &self.size {
            Some(ValidatorSize::Exact(size)) => item.size == *size,
            Some(ValidatorSize::Diff(diff)) => item.url.as_str().len().abs_diff(item.size) == *diff,
            None => true,
        }
    }
}

impl std::fmt::Display for Validator {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if let Some(redirect_url) = &self.redirect_url {
            write!(f, "(CODE:{}|DEST:{})", self.code, redirect_url)
        } else if let Some(ValidatorSize::Exact(size)) = &self.size {
            write!(f, "(CODE:{}|SIZE:{})", self.code, size)
        } else if let Some(ValidatorSize::Diff(diff)) = &self.size {
            write!(f, "(CODE:{}|DIFF_SIZE:{})", self.code, diff)
        } else {
            write!(f, "(CODE:{})", self.code)
        }
    }
}

fn common<T: Clone + PartialEq>(values: &[T]) -> Option<T> {
    if values.len() < 2 {
        return values.first().cloned();
    }
    if values[0] == values[1] || values[0] == values[2] {
        Some(values[0].clone())
    } else if values[1] == values[2] {
        Some(values[1].clone())
    } else {
        None
    }
}

fn get_validator(
    client: &mut CurlClient,
    folder: &Url,
    opts: &GlobalOpts,
) -> Option<Validator> {
    let mut samples = Vec::new();
    for length in [10usize, 20, 30] {
        let random: String = rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(length)
            .map(char::from)
            .collect();
        let url = folder.join(&random).unwrap();
        samples.push(request(client, &url, false, opts));
    }

    let codes: Vec<u32> = samples.iter().map(|item| item.code).collect();
    let code = common(&codes).unwrap_or(404);
    if code == 0 {
        return None;
    }
    if code == 404 {
        return Some(Validator {
            code,
            redirect_url: None,
            size: None,
        });
    }

    let redirects: Vec<Option<String>> = samples
        .iter()
        .map(|item| {
            if item.redirect_url.is_empty() {
                None
            } else {
                Some(item.redirect_url.clone())
            }
        })
        .collect();
    let redirect_url = common(&redirects).unwrap_or_default();
    if redirect_url.is_some() {
        return Some(Validator {
            code,
            redirect_url,
            size: None,
        });
    }

    let sizes: Vec<usize> = samples.iter().map(|item| item.size).collect();
    let size = if let Some(size) = common(&sizes) {
        Some(ValidatorSize::Exact(size))
    } else {
        let diffs: Vec<usize> = samples
            .iter()
            .map(|item| item.url.as_str().len().abs_diff(item.size))
            .collect();
        common(&diffs).map(ValidatorSize::Diff)
    };

    Some(Validator {
        code,
        redirect_url: None,
        size,
    })
}

#[derive(Clone)]
pub struct ScanJob {
    pub host: Url,
    pub folder: Url,
    pub validator: Option<Validator>,
    pub split: u32,
}

pub enum ScanMessage {
    Initial,
    Start(Vec<ScanJob>, Sender<()>),
    QueueDirectory(Url, Url),
    WorkerFinished,
}

enum Validation {
    Scan(Option<Validator>),
    Skip,
}

fn validate_directory(
    client: &mut CurlClient,
    folder: &Url,
    opts: &GlobalOpts,
    output_tx: &Sender<OutputMessage>,
) -> Validation {
    if !opts.validator_enabled() {
        return Validation::Scan(None);
    }
    let Some(validator) = get_validator(client, folder, opts) else {
        let _ = output_tx.send(OutputMessage::Warning(format!(
            "[WARN] {} errored too often during validation, skipping scanning",
            folder
        )));
        return Validation::Skip;
    };
    let _ = output_tx.send(OutputMessage::Info(format!(
        "[INFO] Detected nonexistent paths for {} are {}",
        folder, validator
    )));
    if validator.code == 401 && !opts.scan_401 {
        let _ = output_tx.send(OutputMessage::Info(format!(
            "[INFO] Skipping {}: \n    Scanning of directories returning 401 is disabled.\n    Use the --scan-401 flag to scan this directory,\n    or provide a valid session token or credentials.",
            folder
        )));
        return Validation::Skip;
    }
    if validator.code == 403 && !opts.scan_403 {
        let _ = output_tx.send(OutputMessage::Info(format!(
            "[INFO] Skipping {}: \n    Scanning of directories returning 403 is disabled.\n    Use the --scan-403 flag to scan this directory,\n    or provide valid session token or credentials.",
            folder
        )));
        return Validation::Skip;
    }
    Validation::Scan(Some(validator))
}

fn initial_split(host: &Url, opts: &GlobalOpts, output_tx: &Sender<OutputMessage>) -> u32 {
    let computed = opts.max_threads.saturating_sub(2) / opts.hosts.len() as u32;
    if computed > opts.wordlist_split {
        let _ = output_tx.send(OutputMessage::Info(format!(
            "[INFO] Increasing wordlist-split for initial scan of {} to {}",
            host, computed
        )));
        computed
    } else {
        opts.wordlist_split
    }
}

fn path_segment_count(url: &Url) -> i32 {
    url.path_segments().unwrap().count() as i32
}

fn relative_depth(folder: &Url, host: &Url) -> i32 {
    path_segment_count(folder) - path_segment_count(host)
}

fn can_queue_directory(item: &ContentItem, host: &Url, opts: &GlobalOpts) -> bool {
    if opts.disable_recursion {
        return false;
    }
    if item.is_listable && !opts.scan_listable {
        return false;
    }
    if let Some(max_depth) = opts.max_recursion_depth {
        if relative_depth(&item.url, host) > max_depth {
            return false;
        }
    }
    true
}

fn should_fetch_scraped(item: &ContentItem, opts: &GlobalOpts) -> bool {
    if opts.disable_recursion {
        return false;
    }
    match opts.max_recursion_depth {
        None => true,
        Some(max_depth) => path_segment_count(&item.url) < max_depth,
    }
}

fn passes_filters(item: &ContentItem, job: &ScanJob, opts: &GlobalOpts) -> bool {
    if !opts.code_whitelist.is_empty() && !opts.code_whitelist.contains(&item.code) {
        log::trace!("[{}]: code {} not in whitelist", item.url, item.code);
        return false;
    }
    if opts.code_blacklist.contains(&item.code) {
        log::trace!("[{}]: code {} in blacklist", item.url, item.code);
        return false;
    }
    if item.code == 0 {
        log::trace!("[{}]: code 0 detected", item.url);
        return false;
    }
    if let Some(validator) = &job.validator {
        if validator.matches(item) {
            log::trace!("[{}]: matches Not Found condition", item.url);
            return false;
        }
    }
    if opts
        .length_blacklist
        .iter()
        .any(|range| range.contains(&item.size))
    {
        log::trace!(
            "[{}]: length {} is in a blacklist range",
            item.url,
            item.size
        );
        return false;
    }
    true
}

fn decode_html_entities(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    let mut chars = value.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '&' {
            output.push(c);
            continue;
        }
        let mut entity = String::new();
        let mut terminated = false;
        for next in chars.by_ref() {
            if next == ';' {
                terminated = true;
                break;
            }
            entity.push(next);
            if entity.len() > 16 {
                break;
            }
        }
        if !terminated {
            output.push('&');
            output.push_str(&entity);
            continue;
        }
        let decoded = match entity.as_str() {
            "amp" => Some('&'),
            "lt" => Some('<'),
            "gt" => Some('>'),
            "quot" => Some('"'),
            "apos" => Some('\''),
            _ if entity.starts_with("#x") || entity.starts_with("#X") => {
                u32::from_str_radix(&entity[2..], 16).ok().and_then(char::from_u32)
            }
            _ if entity.starts_with('#') => {
                entity[1..].parse::<u32>().ok().and_then(char::from_u32)
            }
            _ => None,
        };
        if let Some(decoded) = decoded {
            output.push(decoded);
        } else {
            output.push('&');
            output.push_str(&entity);
            output.push(';');
        }
    }
    output
}

fn extract_hrefs(html: &str) -> Vec<String> {
    let bytes = html.as_bytes();
    let mut hrefs = Vec::new();
    let mut index = 0usize;
    while index + 1 < bytes.len() {
        if bytes[index] != b'<' {
            index += 1;
            continue;
        }
        if html[index..].starts_with("<!--") {
            if let Some(end) = html[index + 4..].find("-->") {
                index += 4 + end + 3;
            } else {
                break;
            }
            continue;
        }
        if bytes[index + 1] != b'a' {
            index += 1;
            continue;
        }
        let after_a = index + 2;
        if after_a < bytes.len()
            && !(bytes[after_a].is_ascii_whitespace() || bytes[after_a] == b'>' || bytes[after_a] == b'/')
        {
            index = after_a;
            continue;
        }

        let mut cursor = after_a;
        let mut href: Option<String> = None;
        while cursor < bytes.len() {
            while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                cursor += 1;
            }
            if cursor >= bytes.len() || bytes[cursor] == b'>' {
                cursor += 1;
                break;
            }
            if bytes[cursor] == b'/' {
                cursor += 1;
                continue;
            }
            let name_start = cursor;
            while cursor < bytes.len()
                && !bytes[cursor].is_ascii_whitespace()
                && bytes[cursor] != b'='
                && bytes[cursor] != b'>'
                && bytes[cursor] != b'/'
            {
                cursor += 1;
            }
            let name = &html[name_start..cursor];
            while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                cursor += 1;
            }
            let mut value = String::new();
            if cursor < bytes.len() && bytes[cursor] == b'=' {
                cursor += 1;
                while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                    cursor += 1;
                }
                if cursor < bytes.len() && (bytes[cursor] == b'"' || bytes[cursor] == b'\'') {
                    let quote = bytes[cursor];
                    cursor += 1;
                    let value_start = cursor;
                    while cursor < bytes.len() && bytes[cursor] != quote {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                    if cursor < bytes.len() {
                        cursor += 1;
                    }
                } else {
                    let value_start = cursor;
                    while cursor < bytes.len()
                        && !bytes[cursor].is_ascii_whitespace()
                        && bytes[cursor] != b'>'
                    {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                }
            }
            if name == "href" && href.is_none() {
                href = Some(decode_html_entities(&value));
            }
        }
        if let Some(href) = href {
            hrefs.push(href);
        }
        index = cursor.max(index + 1);
    }
    hrefs
}

fn scrape_listable(item: &ContentItem) -> Vec<ContentItem> {
    let base = item.url.to_string();
    let mut scraped = Vec::new();
    for href in extract_hrefs(&item.contents) {
        if href.is_empty()
            || href.starts_with('?')
            || href.starts_with("./")
            || href.starts_with("../")
        {
            continue;
        }
        let candidate = if href.contains("://") {
            href.clone()
        } else if let Some(stripped) = href.strip_prefix('/') {
            format!("{}/{}", item.url.origin().ascii_serialization(), stripped)
        } else {
            format!("{}{}", base, href)
        };
        if candidate == base || !candidate.starts_with(&base) {
            continue;
        }
        if let Ok(url) = Url::parse(&candidate) {
            let mut found = ContentItem::new(url, href.ends_with('/'));
            found.found_from_listable = true;
            scraped.push(found);
        }
    }
    scraped
}

fn queue_directory(
    item: &ContentItem,
    job: &ScanJob,
    opts: &GlobalOpts,
    scan_tx: &Sender<ScanMessage>,
) {
    if can_queue_directory(item, &job.host, opts) {
        let _ = scan_tx.send(ScanMessage::QueueDirectory(
            job.host.clone(),
            item.url.clone(),
        ));
    }
}

fn process_item(
    item: ContentItem,
    job: &ScanJob,
    client: &mut CurlClient,
    opts: &GlobalOpts,
    output_tx: &Sender<OutputMessage>,
    scan_tx: &Sender<ScanMessage>,
) {
    if item.is_directory {
        let _ = output_tx.send(OutputMessage::Item(job.host.clone(), item.clone()));

        if item.is_listable && opts.scrape_listable {
            let scraped = scrape_listable(&item);
            for found in scraped.iter().filter(|found| found.is_directory) {
                if should_fetch_scraped(found, opts) {
                    let fetched = request(client, &found.url, true, opts);
                    process_item(fetched, job, client, opts, output_tx, scan_tx);
                } else {
                    let _ = output_tx.send(OutputMessage::Item(job.host.clone(), found.clone()));
                    queue_directory(found, job, opts, scan_tx);
                }
            }
            for found in scraped.iter().filter(|found| !found.is_directory) {
                let _ = passes_filters(found, job, opts);
            }
        }

        queue_directory(&item, job, opts, scan_tx);
    } else if passes_filters(&item, job, opts) {
        let _ = output_tx.send(OutputMessage::Item(job.host.clone(), item));
    }
}

fn request_thread(
    job: ScanJob,
    words: Vec<String>,
    opts: Arc<GlobalOpts>,
    output_tx: Sender<OutputMessage>,
    scan_tx: Sender<ScanMessage>,
) {
    log::debug!("Scanning {}", job.folder);
    let mut client = CurlClient::new();
    let mut consecutive_errors = 0u32;

    for word in &words {
        let url = job.folder.join(word).unwrap();
        let item = request(&mut client, &url, false, &opts);
        let is_directory = item.is_directory;
        let code = item.code;
        let item_url = item.url.clone();
        process_item(item, &job, &mut client, &opts, &output_tx, &scan_tx);

        if is_directory {
            consecutive_errors = 0;
        } else if code == 0 {
            consecutive_errors += 1;
            if opts.max_errors != 0 && consecutive_errors >= opts.max_errors {
                let _ = output_tx.send(OutputMessage::Warning(format!(
                    "[WARN] Thread scanning {} stopping due to multiple consecutive errors received",
                    item_url
                )));
                break;
            }
        } else {
            consecutive_errors = 0;
        }

        if let Some(throttle) = opts.throttle {
            thread::sleep(Duration::from_millis(throttle as u64));
