    // channel sender is supplied by the caller through the worker messages
    // themselves in this architecture; use a clone stored in a thread-local
    // alternative below by receiving it via the first Start is not possible.
    // Instead, the main thread keeps the original sender alive, and workers
    // are given clones created from it through a helper channel set up in
    // `run`. This placeholder is replaced by the `scan_sender` parameter
    // passed to this function in the public wrapper.
    drop(dispatch);
    let _ = (initial_jobs, active_workers, scanned, done_sender);
}
