fn decode_html_entities(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    let mut chars = value.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '&' {
            output.push(c);
            continue;
        }
        let mut entity = String::new();
        let mut terminated = false;
        for next in chars.by_ref() {
            if next == ';' {
                terminated = true;
                break;
            }
            entity.push(next);
            if entity.len() > 16 {
                break;
            }
        }
        if !terminated {
            output.push('&');
            output.push_str(&entity);
            continue;
        }
        let decoded = match entity.as_str() {
            "amp" => Some('&'),
            "lt" => Some('<'),
            "gt" => Some('>'),
            "quot" => Some('"'),
            "apos" => Some('\''),
            _ if entity.starts_with("#x") || entity.starts_with("#X") => {
                u32::from_str_radix(&entity[2..], 16).ok().and_then(char::from_u32)
            }
            _ if entity.starts_with('#') => {
                entity[1..].parse::<u32>().ok().and_then(char::from_u32)
            }
            _ => None,
        };
        if let Some(decoded) = decoded {
            output.push(decoded);
        } else {
            output.push('&');
            output.push_str(&entity);
            output.push(';');
        }
    }
    output
}

fn extract_hrefs(html: &str) -> Vec<String> {
    let bytes = html.as_bytes();
    let mut hrefs = Vec::new();
    let mut index = 0usize;
    while index + 1 < bytes.len() {
        if bytes[index] != b'<' {
            index += 1;
            continue;
        }
        if html[index..].starts_with("<!--") {
            if let Some(end) = html[index + 4..].find("-->") {
                index += 4 + end + 3;
            } else {
                break;
            }
            continue;
        }
        if bytes[index + 1] != b'a' {
            index += 1;
            continue;
        }
        let after_a = index + 2;
        if after_a < bytes.len()
            && !(bytes[after_a].is_ascii_whitespace() || bytes[after_a] == b'>' || bytes[after_a] == b'/')
        {
            index = after_a;
            continue;
        }

        let mut cursor = after_a;
        let mut href: Option<String> = None;
        while cursor < bytes.len() {
            while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                cursor += 1;
            }
            if cursor >= bytes.len() || bytes[cursor] == b'>' {
                cursor += 1;
                break;
            }
            if bytes[cursor] == b'/' {
                cursor += 1;
                continue;
            }
            let name_start = cursor;
            while cursor < bytes.len()
                && !bytes[cursor].is_ascii_whitespace()
                && bytes[cursor] != b'='
                && bytes[cursor] != b'>'
                && bytes[cursor] != b'/'
            {
                cursor += 1;
            }
            let name = &html[name_start..cursor];
            while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                cursor += 1;
            }
            let mut value = String::new();
            if cursor < bytes.len() && bytes[cursor] == b'=' {
                cursor += 1;
                while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                    cursor += 1;
                }
                if cursor < bytes.len() && (bytes[cursor] == b'"' || bytes[cursor] == b'\'') {
                    let quote = bytes[cursor];
                    cursor += 1;
                    let value_start = cursor;
                    while cursor < bytes.len() && bytes[cursor] != quote {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                    if cursor < bytes.len() {
                        cursor += 1;
                    }
                } else {
                    let value_start = cursor;
                    while cursor < bytes.len()
                        && !bytes[cursor].is_ascii_whitespace()
                        && bytes[cursor] != b'>'
                    {
                        cursor += 1;
                    }
                    value = html[value_start..cursor].to_owned();
                }
            }
            if name == "href" && href.is_none() {
                href = Some(decode_html_entities(&value));
            }
        }
        if let Some(href) = href {
            hrefs.push(href);
        }
        index = cursor.max(index + 1);
    }
    hrefs
}

fn scrape_listable(item: &ContentItem) -> Vec<ContentItem> {
    let base = item.url.to_string();
    let mut scraped = Vec::new();
    for href in extract_hrefs(&item.contents) {
        if href.is_empty()
            || href.starts_with('?')
            || href.starts_with("./")
            || href.starts_with("../")
        {
            continue;
        }
        let candidate = if href.contains("://") {
            href.clone()
        } else if let Some(stripped) = href.strip_prefix('/') {
            format!("{}/{}", item.url.origin().ascii_serialization(), stripped)
        } else {
            format!("{}{}", base, href)
        };
        if candidate == base || !candidate.starts_with(&base) {
            continue;
        }
        if let Ok(url) = Url::parse(&candidate) {
            let mut found = ContentItem::new(url, href.ends_with('/'));
            found.found_from_listable = true;
            scraped.push(found);
