            for found in scraped.iter().filter(|found| !found.is_directory) {
                let _ = passes_filters(found, job, opts);
            }
        }

        queue_directory(&item, job, opts, scan_tx);
    } else if passes_filters(&item, job, opts) {
        let _ = output_tx.send(OutputMessage::Item(job.host.clone(), item));
    }
}

fn request_thread(
    job: ScanJob,
    words: Vec<String>,
    opts: Arc<GlobalOpts>,
    output_tx: Sender<OutputMessage>,
    scan_tx: Sender<ScanMessage>,
) {
