        let thread_id = format!("{:?}", thread::current().id());
        let thread_number = thread_id
            .trim_start_matches("ThreadId(")
            .trim_end_matches(')');
        let location = if record.level() == Level::Trace {
            match (record.file(), record.line()) {
                (Some(file), Some(line)) => format!("[{}:{}] ", file, line),
                _ => String::new(),
            }
        } else {
            String::new()
        };
        println!(
            "{} [{}] ({}) {}: {}{}",
            chrono::Local::now().format("%H:%M:%S"),
            record.level(),
            thread_number,
            record.target(),
            location,
            record.args()
        );
    }

    fn flush(&self) {}
}

fn init_logger(verbose: u8) {
    let level = match verbose {
        0 => LevelFilter::Error,
        1 => LevelFilter::Debug,
        _ => LevelFilter::Trace,
    };
    let _ = log::set_logger(&LOGGER);
    log::set_max_level(level);
}

pub fn find_default_wordlist() -> Option<PathBuf> {
    let executable = std::env::current_exe().unwrap();
    let folder = executable.parent().unwrap();
    let candidates = vec![
        folder.join("dirble_wordlist.txt"),
        PathBuf::from("/usr/share/dirble/dirble_wordlist.txt"),
        PathBuf::from("/usr/share/wordlists/dirble_wordlist.txt"),
        PathBuf::from("/usr/share/wordlists/dirble/dirble_wordlist.txt"),
    ];
    log::debug!(
        "Checking for wordlist in:\n - {}\n - {}\n - {}\n - {}",
        candidates[0].display(),
        candidates[1].display(),
        candidates[2].display(),
        candidates[3].display()
    );
    candidates.into_iter().find(|candidate| candidate.exists())
}

fn print_banner(opts: &GlobalOpts) {
    println!("Dirble 1.4.2 (commit c11e5cd, build 2026-08-10)");
    println!("Developed by Izzy Whistlecroft");
    println!(
        "Targets: {}",
        opts.hosts
            .iter()
            .map(|host| host.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
    println!(
        "Wordlists: {}",
        opts.wordlist_paths
            .iter()
            .map(|path| path.display().to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );

    let prefixes: Vec<&String> = opts.prefixes.iter().filter(|prefix| !prefix.is_empty()).collect();
    if prefixes.is_empty() {
        println!("No Prefixes");
    } else {
        println!(
            "Prefixes: {}",
            prefixes
                .iter()
                .map(|prefix| prefix.as_str())
                .collect::<Vec<_>>()
                .join(" ")
        );
    }

    let extensions: Vec<&String> = opts
        .extensions
        .iter()
        .filter(|extension| !extension.is_empty())
        .collect();
    if extensions.is_empty() {
        println!("No Extensions");
    } else {
        println!(
            "Extensions: {}",
            extensions
                .iter()
                .map(|extension| extension.as_str())
                .collect::<Vec<_>>()
                .join(" ")
        );
    }

    if opts.length_blacklist.is_empty() {
        println!("No lengths hidden");
    } else {
        let lengths: Vec<String> = opts
            .length_blacklist
            .iter()
            .map(|range| {
                if range.end == range.start.wrapping_add(1) {
                    range.start.to_string()
                } else {
                    format!("{}-{}", range.start, range.end.wrapping_sub(1))
                }
            })
            .collect();
        println!("Hidden lengths: [{}]", lengths.join(", "));
    }
    println!();
}

pub fn run() {
    let matches = arg_parse::command().get_matches();
    init_logger(matches.get_count("verbose"));

    let Some(global_opts) = arg_parse::get_global_opts(&matches) else {
        eprintln!("[ERROR] Unable to find default wordlist");
        process::exit(1);
    };
    let opts = Arc::new(global_opts);
    let interactive = std::io::stdout().is_terminal();
    if interactive {
        print_banner(&opts);
    }

    for host in opts.hosts.iter() {
        let _ = host.path_segments().unwrap();
    }

    let (output_tx, output_rx) = mpsc::channel::<OutputMessage>();
    let (scan_tx, scan_rx) = mpsc::channel::<ScanMessage>();
    let (initial_tx, initial_rx) = mpsc::channel();

    let manager_output_tx = output_tx.clone();
    let manager_scan_tx = scan_tx.clone();
    let manager_opts = Arc::clone(&opts);
    let manager_thread = thread::spawn(move || {
        request_thread::scan_manager(
            scan_rx,
            manager_scan_tx,
            initial_tx,
            manager_output_tx,
            manager_opts,
        )
    });

    let output_hosts: Vec<_> = opts.hosts.iter().cloned().collect();
    let output_config = OutputConfig {
        silent: opts.silent,
        show_htaccess: opts.show_htaccess,
        interactive,
        no_color: opts.no_color,
    };
    let output_thread = thread::spawn(move || {
        output_thread::output_thread(output_rx, output_hosts, output_config)
    });

    let _ = scan_tx.send(ScanMessage::Initial);
    let initial_jobs = initial_rx.recv().unwrap();

    let files = output::create_output_files(&opts.output_file, &opts.json_file, &opts.xml_file);
    let _ = output_tx.send(OutputMessage::Files(files));

    let (done_tx, done_rx) = mpsc::channel::<()>();
    let monitor_output_tx = output_tx.clone();
    let monitor_thread = thread::spawn(move || {
        if done_rx.recv().is_ok() {
            let _ = monitor_output_tx.send(OutputMessage::Finish);
        } else {
            loop {
                thread::park();
            }
        }
    });

    let _ = scan_tx.send(ScanMessage::Start(initial_jobs, done_tx));
    drop(output_tx);
    drop(scan_tx);

    output_thread.join().unwrap();
    let _ = monitor_thread.join();
    let _ = manager_thread.join();
}
