import pty,os,subprocess,sys
sys.path.insert(0,"/tmp");from harness import Server
routes={"/a":(200,"A",{})}
with Server(routes) as srv:
 open("/tmp/wl.txt","w").write("a\n")
 def run(exe,term,tty=True,extraenv={}):
  env=dict(os.environ);env.pop("TERM",None)
  if term is not None:env["TERM"]=term
  env.update(extraenv)
