    let mut active_workers = 0usize;
    let mut pending_jobs: VecDeque<ScanJob> = initial_jobs.into_iter().collect();
    let mut current_job: Option<CurrentJob> = None;

    loop {
        while (active_workers as u32) < opts.max_threads {
            if current_job.is_none() {
                if let Some(job) = pending_jobs.pop_front() {
                    current_job = Some(CurrentJob::new(job));
                } else {
                    break;
                }
            }
            let current = current_job.as_mut().unwrap();
